import { deepStrictEqual, strictEqual } from 'node:assert/strict';
import { test } from 'node:test';
import { requestApp } from '../../scripts/request-app.mjs';
import { createApp } from '../../src/server.js';

test('GET /api/users rejects a missing Authorization header', async () => {
  const response = await requestApp(createApp(), '/api/users');

  strictEqual(response.status, 401);
  deepStrictEqual(JSON.parse(response.body), { error: 'unauthorized' });
});

test('GET /api/users accepts an authorized caller', async () => {
  const response = await requestApp(createApp(), '/api/users', {
    headers: { authorization: 'Bearer demo-token' }
  });

  strictEqual(response.status, 200);
  deepStrictEqual(JSON.parse(response.body), [{ id: 'u_123', role: 'admin' }]);
});
